js.text:

function grid$qldctcccd_1(f){
  this.constructor(f);
}
grid$qldctcccd_1.prototype = new DirEvent();
grid$qldctcccd_1.prototype.afterInit = function(){
  var p = this._dir, g = p.grid(), dt = g.data, pa = p.options.dirAbove, ga = pa.grid(), ra = ga._currRow||0;
  	this.FormSentData(p);
    this.refreshSub();
}
grid$qldctcccd_1.prototype.refreshSub = function () {
  var p = this._dir, g = p.grid(), dt = g.data, pa = p.options.dirAbove, ga = pa.grid(), ra = ga._currRow||0;
  const btnThem = document.getElementById("TOOLBAR_qldctcccd_1_0_add");

  if (ga.data.count() == 0) {
  	if (btnThem) {
		btnThem.style.pointerEvents = "none";  // Vô hiệu hóa click
		btnThem.style.opacity = "0.5";         // Làm mờ nút để biết là bị khóa
		btnThem.title = "Nút này đã bị khóa";
	}

	p.setSubtitle(['%s1', '_'])

	return;
  }

  	p.setSubtitle(['%s1', pa.valGrid(ra, 'ma_hogiadinh', 0)]);
}
grid$qldctcccd_1.prototype.FormSentData = function (p) {
	maHogiadinh = p.options.memvars.val('ma_hogiadinh');
	maTTP = p.options.memvars.val('ma_ttp');
	maPhuongXa = p.options.memvars.val('ma_phuongxa');
	maKhuPho = p.options.memvars.val('ma_khupho');
	diaChi = p.options.memvars.val('dia_chi');

	p.options._ma_hogiadinh =  maHogiadinh;
	p.options._ma_ttp =  maTTP;
	p.options._ma_phuongxa =  maPhuongXa;
	p.options._ma_khupho =  maKhuPho;
	p.options._dia_chi =  diaChi;

}

css.text:

.tree-form{
	width: 250px;
}
.ic-view-dept{
  background-position: 0px 0px;
}
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 50%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
